# patch_20261010_marketing_country_names.ps1
# /marketing: include / exclude countries become name-based multi-selects
# (names from app.countries). Replaces 2 files and adds 1, ONLY if each existing
# file still matches the reviewed original (LF-normalized SHA-256). Idempotent.
$Repo = "C:\dev\mbg-project"
function Sha([string]$t) { $b = [System.Text.Encoding]::UTF8.GetBytes($t); $h = [System.Security.Cryptography.SHA256]::Create().ComputeHash($b); ($h | ForEach-Object { $_.ToString("x2") }) -join "" }
$items = @(
  @{ Path = "src\app\(app)\marketing\marketing-client.tsx"; Old = "07c5c67aaa1bec85f25ce23f29f61dc5c5b9fb47056c155b99304ce9a94f1a77"; New = "7a93e0e9c2bfadbd0bddd3752432ebd0f1a833422502bc8148ad6e84f1375293"; B64 = "" },
  @{ Path = "src\app\(app)\marketing\page.tsx"; Old = "142b808449edb22cba37968c8a321d8dd216a13808bd031da86cfb5dbfe836a5"; New = "d1d7d503f122b708f8937eb0b5bdf830386d5743a52d07b4daff59fd8d3a99ac"; B64 = "" },
  @{ Path = "src\components\marketing\country-multi-select.tsx"; Old = "ABSENT"; New = "db360a84db9d30ab69cfcb670694c8ddb1178091ee3110ceedb8858590738392"; B64 = "" }
)
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  if (-not (Test-Path -LiteralPath $p)) { if ($it.Old -eq "ABSENT") { continue } ; Write-Output ("ERROR missing " + $it.Path); return }
  $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
  if ($cur -ne $it.Old -and $cur -ne $it.New) { Write-Output ("ERROR changed since review, not patched: " + $it.Path); return }
}
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  if (Test-Path -LiteralPath $p) {
    $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
    if ($cur -eq $it.New) { Write-Output ("SKIP  already patched " + $it.Path); continue }
  } else { [System.IO.Directory]::CreateDirectory((Split-Path -LiteralPath $p)) | Out-Null }
  [System.IO.File]::WriteAllBytes($p, [System.Convert]::FromBase64String($it.B64))
  Write-Output ("PATCHED " + $it.Path)
}
